"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([[5230],{41139(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>u,default:()=>d,frontMatter:()=>o,metadata:()=>i,toc:()=>a});const i=JSON.parse('{"id":"scolarite/cpbx/s4/informatique/projet-reverso","title":"Projet Reverso : fichier de synth\xe8se","description":"Fichier de synth\xe8se du projet informatique du groupe C : conception du client et du serveur du jeu Reverso en Python avec Tkinter et PodSixNet, d\xe9roulement d\'une partie, id\xe9es d\'am\xe9liorations et appr\xe9ciation du cours.","source":"@site/docs/scolarite/cpbx/s4/informatique/projet-reverso.md","sourceDirName":"scolarite/cpbx/s4/informatique","slug":"/scolarite/cpbx/s4/informatique/projet-reverso","permalink":"/docs/scolarite/cpbx/s4/informatique/projet-reverso","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1792955287000,"sidebarPosition":1,"frontMatter":{"title":"Projet Reverso : fichier de synth\xe8se","description":"Fichier de synth\xe8se du projet informatique du groupe C : conception du client et du serveur du jeu Reverso en Python avec Tkinter et PodSixNet, d\xe9roulement d\'une partie, id\xe9es d\'am\xe9liorations et appr\xe9ciation du cours.","sidebar_position":1},"sidebar":"tutorialSidebar","previous":{"title":"Informatique","permalink":"/docs/scolarite/cpbx/s4/informatique/"},"next":{"title":"Calcul diff\xe9rentiel","permalink":"/docs/scolarite/cpbx/s4/calcul-differentiel/"}}');var r=t(74848),s=t(28453);const o={title:"Projet Reverso : fichier de synth\xe8se",description:"Fichier de synth\xe8se du projet informatique du groupe C : conception du client et du serveur du jeu Reverso en Python avec Tkinter et PodSixNet, d\xe9roulement d'une partie, id\xe9es d'am\xe9liorations et appr\xe9ciation du cours.",sidebar_position:1},u=void 0,l={},a=[{value:"Introduction",id:"introduction",level:2},{value:"Conception du jeu",id:"conception-du-jeu",level:2},{value:"Le client",id:"le-client",level:3},{value:"Le serveur",id:"le-serveur",level:3},{value:"D\xe9roulement d&#39;une partie",id:"d\xe9roulement-dune-partie",level:2},{value:"Id\xe9es d&#39;am\xe9liorations",id:"id\xe9es-dam\xe9liorations",level:2},{value:"Appr\xe9ciation du cours d&#39;informatique",id:"appr\xe9ciation-du-cours-dinformatique",level:2}];function c(e){const n={em:"em",h2:"h2",h3:"h3",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components},{Katex:t}=n;return t||function(e,n){throw new Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Katex",!0),(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.h2,{id:"introduction",children:"Introduction"}),"\n",(0,r.jsx)(n.p,{children:"Ce document est le document explicatif du jeu Reverso propos\xe9 par le groupe C. Le but de ce document est d'expliquer la conception du jeu, le fonctionnement de ce dernier et des pistes d'am\xe9liorations du jeu. En somme, ce document devrait permettre \xe0 quelqu'un qui veut continuer le d\xe9veloppement de ce jeu de le faire dans de bonnes conditions."}),"\n",(0,r.jsx)(n.h2,{id:"conception-du-jeu",children:"Conception du jeu"}),"\n",(0,r.jsx)(n.p,{children:"Comme demand\xe9 dans les consignes, ce projet est s\xe9par\xe9 en deux parties : une d\xe9di\xe9e \xe0 la gestion du serveur et du tournoi, l'autre au client se connectant au serveur."}),"\n",(0,r.jsx)(n.h3,{id:"le-client",children:"Le client"}),"\n",(0,r.jsx)(n.p,{children:"Nous avons d\xfb r\xe9fl\xe9chir judicieusement au choix de la d\xe9finition de notre terrain. En effet, ce choix va totalement influencer la totalit\xe9 de notre projet."}),"\n",(0,r.jsxs)(n.p,{children:["Nous avons donc choisi de d\xe9finir une double liste (grille) de dimension \xe9gale \xe0 celle du terrain de jeu (",(0,r.jsx)(t,{tex:"6 \\times 6"}),"). Nous avons nomm\xe9 cette grille ",(0,r.jsx)(n.strong,{children:"tjeu"}),". Dans cette grille, nous pouvons avoir 3 \xe9tats. Un 0 correspond \xe0 une case vide (en r\xe9alit\xe9 la case n'est pas vide, le pion est dessin\xe9 mais de la m\xeame couleur que le fond, donc vide), un 1 correspond \xe0 une case avec un pion blanc (alli\xe9) et un 2 correspond \xe0 une case avec un pion noir (adverse). ",(0,r.jsx)(n.strong,{children:"tjeu"})," est initialement vide (d\xe9finie \xe0 la fin de ",(0,r.jsx)(n.em,{children:"clientC.py"}),") ; elle est remplie gr\xe2ce \xe0 la fonction ",(0,r.jsx)(n.em,{children:"initJeu"}),". Cette fonction fait partie de la classe \xab fenetre \xbb et permet d'initialiser le jeu, c'est-\xe0-dire remplir ",(0,r.jsx)(n.strong,{children:"tjeu"})," avec des 0 sauf les cases centrales, comme expliqu\xe9 dans les r\xe8gles du jeu. Cette fonction fait appel \xe0 ",(0,r.jsx)(n.em,{children:"traceGrille"})," (qui fait elle-m\xeame appel \xe0 ",(0,r.jsx)(n.em,{children:"affichePion"}),"), qui permet de transformer les valeurs de ",(0,r.jsx)(n.strong,{children:"tjeu"})," en pions sur le plateau."]}),"\n",(0,r.jsx)(n.p,{children:"La classe \xab fenetre \xbb permet de d\xe9finir la fen\xeatre g\xe9n\xe9rale de jeu, c'est-\xe0-dire celle o\xf9 apparaissent le titre du jeu et le bouton d'aide (permettant d'afficher les r\xe8gles du jeu). Sur la droite, nous avons le bouton permettant de passer, le terrain d\xe9fini pr\xe9c\xe9demment, le nombre de jetons blancs, de jetons noirs et le nombre de jetons restants. Sur la gauche, nous avons la gestion du tournoi."}),"\n",(0,r.jsxs)(n.p,{children:["Nous avons aussi impl\xe9ment\xe9 des fonctions utiles dans cette classe ; parmi elles, nous avons ",(0,r.jsx)(n.em,{children:"comptePions"}),", qui permet de compter le nombre de pions et de l'afficher sur la fen\xeatre du jeu. Nous avons une autre fonction utile, ",(0,r.jsx)(n.em,{children:"clearCanvas"}),", qui permet simplement d'effacer la totalit\xe9 du plateau."]}),"\n",(0,r.jsxs)(n.p,{children:["Finalement, cette classe h\xe9berge l'une des fonctions les plus importantes de notre jeu, la fonction ",(0,r.jsx)(n.em,{children:"mouseClic"}),", qui permet de v\xe9rifier, lorsque l'on clique sur une case (id est que l'on veut poser une pi\xe8ce), si l'emplacement de cette pi\xe8ce est valide ou non, et d'afficher ce pion tout en transformant les pions qu'il doit transformer. C'est gr\xe2ce \xe0 cette fonction que nous pouvons permettre au joueur de jouer en respectant les r\xe8gles du jeu."]}),"\n",(0,r.jsx)(n.p,{children:"Gr\xe2ce \xe0 ces quelques fonctions, nous pouvons d\xe9finir notre terrain de jeu, le modifier \xe0 notre guise et v\xe9rifier si un coup est jouable ou non."}),"\n",(0,r.jsx)(n.p,{children:"La classe client permet de d\xe9finir toutes les fonctions relatives \xe0 l'utilisateur. Lors de son ex\xe9cution (dans un invite de commande), un client se connecte au serveur et permet alors l'ex\xe9cution de plusieurs commandes. Parmi ces derni\xe8res, nous avons une fonction permettant de confirmer la connexion \xe0 un serveur, de commencer la boucle de jeu, d'accepter ou de refuser un pseudo, de quitter le jeu, d'afficher les autres joueurs connect\xe9s, d'envoyer une demande de partie, de refuser une demande, de jouer un coup, d'emp\xeacher le joueur de jouer avec soi-m\xeame, de donner des informations au joueur (comme l'adversaire qui passe, etc.), de g\xe9rer la fin du jeu, etc."}),"\n",(0,r.jsxs)(n.p,{children:["Hormis les fonctions triviales, nous avons deux fonctions essentielles : la fonction ",(0,r.jsx)(n.em,{children:"Networkcoup"}),", qui permet au joueur d'effectuer un coup et d'envoyer les informations relatives \xe0 ce coup au serveur, et la fonction ",(0,r.jsx)(n.em,{children:"NetworkfinJeu"}),", qui permet de communiquer l'information sur la victoire ou la d\xe9faite du joueur et d'afficher cette information."]}),"\n",(0,r.jsx)(n.p,{children:"Nous avons aussi \xe9tabli dans le client quelques fonctions utiles : une fonction permettant de demander le pseudo de l'utilisateur lorsqu'il se connecte (et de le refuser s'il n'est pas bon), une fonction permettant d'afficher les r\xe8gles, une fonction permettant au joueur de passer et une fonction permettant de tester si la partie est finie ou pas. Ces diff\xe9rentes fonctions seront utilis\xe9es dans le d\xe9roulement du jeu."}),"\n",(0,r.jsx)(n.h3,{id:"le-serveur",children:"Le serveur"}),"\n",(0,r.jsx)(n.p,{children:"Ce fichier est divis\xe9 en trois classes : une classe permettant d'\xe9tablir et d'entretenir le lien avec le client, une classe permettant le bon fonctionnement du serveur qui h\xe9berge les diff\xe9rentes parties et une classe qui g\xe8re la partie en elle-m\xeame."}),"\n",(0,r.jsxs)(n.p,{children:["La classe ",(0,r.jsx)(n.em,{children:"ChannelServer"})," est la classe permettant d'entretenir le lien entre le serveur et le client, en somme de g\xe9rer le tournoi. Nous pouvons trouver \xe0 l'int\xe9rieur des fonctions comme celle qui teste si le pseudo est correct, qui le cas \xe9ch\xe9ant refuse le pseudo, ou celle qui d\xe9finit les points initiaux. Cette classe permet aussi de mettre en relation deux clients (de demander une partie, de g\xe9rer l'acceptation ou le refus). \xc9videmment, cette classe permet de transmettre toutes les informations entre les diff\xe9rents clients et le serveur, comme le coup qu'un client a jou\xe9, s'il a pass\xe9, s'il est vainqueur, s'il est perdant, etc. Cette classe est donc centrale dans notre jeu : elle permet la communication globale entre nos deux fichiers, et une bonne conception de cette derni\xe8re simplifie grandement le travail."]}),"\n",(0,r.jsx)(n.p,{children:"Le serveur est l\xe0 pour g\xe9rer ce qui ne communique pas directement avec le client mais qui permet le bon d\xe9roulement d'une partie, c'est-\xe0-dire constituer la liste des joueurs connect\xe9s, cr\xe9er une partie entre deux joueurs, actualiser l'\xe9tat, prendre en compte qu'un joueur passe, tester si le jeu est fini ou non."}),"\n",(0,r.jsx)(n.p,{children:"La classe partie permet de g\xe9rer la partie \xe0 proprement parler. Elle permet d'initialiser cette derni\xe8re en connectant deux joueurs, de g\xe9rer la fin de partie et les scores et de prendre en consid\xe9ration la fin de partie."}),"\n",(0,r.jsx)(n.h2,{id:"d\xe9roulement-dune-partie",children:"D\xe9roulement d'une partie"}),"\n",(0,r.jsxs)(n.p,{children:["Nous allons maintenant expliquer succinctement comment se d\xe9roule une partie. Nous admettons que les joueurs sont connect\xe9s au serveur. Chaque joueur peut alors inviter un autre joueur \xe0 jouer. Lorsqu'il clique sur le bouton \xab inviter \xbb, le client envoie au serveur une demande d'information (",(0,r.jsx)(n.em,{children:"demanderPartie"}),", ",(0,r.jsx)(n.em,{children:"partieRefus"}),", ",(0,r.jsx)(n.em,{children:"partieAccepte"}),", ",(0,r.jsx)(n.em,{children:"requetePartie"}),", ",(0,r.jsx)(n.em,{children:"refusDemande"}),"). Si les deux joueurs ont une occupation \xe9gale \xe0 0 (ils sont libres), le serveur initialise une partie entre ces deux joueurs (",(0,r.jsx)(n.em,{children:"creerPartie"}),", ",(0,r.jsx)(n.em,{children:"initialiserPartie"}),"). Une fois que le lien entre les deux joueurs est \xe9tabli, le serveur dit qui doit jouer en premier. Ce dernier clique, ce qui teste si la case o\xf9 il a cliqu\xe9 est valide ; si c'est le cas, il pose sa pi\xe8ce et retourne les pi\xe8ces qu'il a captur\xe9es (",(0,r.jsx)(n.em,{children:"mouseClic"}),"). Apr\xe8s cela, les informations sur ce coup sont envoy\xe9es au serveur (",(0,r.jsx)(n.em,{children:"coup"}),") puis distribu\xe9es \xe0 l'autre joueur (",(0,r.jsx)(n.em,{children:"actualiserJoueurs"}),"). C'est ensuite \xe0 l'autre joueur de jouer, et ainsi de suite."]}),"\n",(0,r.jsxs)(n.p,{children:["Il est \xe0 noter qu'\xe0 chaque coup, on teste si le jeu est fini ou non. Si c'est le cas, le joueur envoie au serveur l'information qu'il a termin\xe9 le jeu et qu'il est le vainqueur ou le perdant ; il actualise aussi son occupation pour le tournoi. Le serveur distribue ensuite l'information au vainqueur et au perdant (",(0,r.jsx)(n.em,{children:"end"}),", ",(0,r.jsx)(n.em,{children:"testFin"}),", ",(0,r.jsx)(n.em,{children:"finJeu"}),"). Il envoie ensuite la disponibilit\xe9 des joueurs \xe0 tous les joueurs."]}),"\n",(0,r.jsx)(n.h2,{id:"id\xe9es-dam\xe9liorations",children:"Id\xe9es d'am\xe9liorations"}),"\n",(0,r.jsx)(n.p,{children:"Si quelqu'un voulait am\xe9liorer ce jeu, il pourrait :"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"cr\xe9er un outil de d\xe9tection des zones libres o\xf9 poser ses pi\xe8ces. Cet outil r\xe9utiliserait la fonction qui nous permet de savoir si un coup est valide ou pas : \xe0 chaque nouveau tour, on teste sur toutes les cases si le coup est valide ; si oui, on met un petit rond de couleur au centre de cette case, indiquant au joueur qu'il peut poser un pion ici ;"}),"\n",(0,r.jsx)(n.li,{children:"mettre en place un temps pour \xe9viter que les joueurs s'\xe9ternisent devant le jeu, un temps de 1 minute de r\xe9flexion avant de forcer le joueur \xe0 passer."}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"appr\xe9ciation-du-cours-dinformatique",children:"Appr\xe9ciation du cours d'informatique"}),"\n",(0,r.jsx)(n.p,{children:"Ce cours d'informatique nous offre la possibilit\xe9 de voir l'enseignement d'une mani\xe8re diff\xe9rente : nous avons un objectif \xe0 r\xe9aliser et nous devons nous procurer les connaissances n\xe9cessaires pour r\xe9aliser ce projet par nos propres moyens. Cette m\xe9thode p\xe9dagogique peut \xeatre tr\xe8s performante, nous avons engrang\xe9 une quantit\xe9 de connaissances cons\xe9quente et avons r\xe9alis\xe9 quelque chose de concret, mais cela est tr\xe8s perturbant quand nous sommes habitu\xe9s \xe0 avoir des cours tr\xe8s conventionnels."}),"\n",(0,r.jsx)(n.p,{children:"De plus, nous offrir la possibilit\xe9 de cr\xe9er un jeu est une id\xe9e tr\xe8s enrichissante pour nous. Cela nous a permis d'approcher des concepts d'informatique comme la manipulation de Tkinter, le concept de classe, le concept de communication client-serveur de mani\xe8re ludique et agr\xe9able. Ce projet nous a demand\xe9 de nombreuses recherches sur PodSixNet et Tkinter ; de plus, nous avons d\xfb changer plusieurs fois de jeu (le Blokus, puis le jeu de dames, puis le Reverso) car nous ne savions pas quelle difficult\xe9 un jeu pouvait repr\xe9senter."}),"\n",(0,r.jsx)(n.p,{children:"Ce projet est au final une vision in\xe9dite de l'apprentissage \xe0 CPBx ; cela est agr\xe9able et nous aurions aim\xe9 avoir plus de temps pour le terminer, car nous avons mis beaucoup de temps \xe0 nous familiariser avec les outils propos\xe9s."})]})}function d(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},28453(e,n,t){t.d(n,{R:()=>o,x:()=>u});var i=t(96540);const r={},s=i.createContext(r);function o(e){const n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function u(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),i.createElement(s.Provider,{value:n},e.children)}}}]);